mapper.select:
SELECT 
  FROM async_task


        status = #{status}


        AND task_type = #{taskType}


        AND submit_by = #{submitBy}


 ORDER BY create_time DESC, id DESC

mapper.update:
UPDATE async_task SET status = 1, start_time = NOW(), executor_id = #{executorId}, update_time = NOW() WHERE id IN
#{item}
AND status = 0

mapper.delete:
DELETE FROM async_task
 WHERE status IN (2, 3, 4)
   AND finish_time < #{cutoff}
 LIMIT #{limit}
